# =====================================================================
# Runner: execute every embedded phase sequentially in a fresh namespace
# =====================================================================
import sys as _sys

ROOT = os.path.dirname(os.path.abspath(__file__))
os.chdir(ROOT)

FAILURES = []
for _name, _enc in _PHASES:
    print()
    print("=" * 70)
    print("PHASE:", _name)
    print("=" * 70)
    _sys.stdout.flush()
    _src = base64.b64decode(_enc).decode("utf-8")
    _code = compile(_src, _name, "exec")
    _ns = {"__name__": "__main__", "__file__": os.path.abspath(_name)}
    try:
        exec(_code, _ns)
        _sys.stdout.flush()
        print("[OK]  ", _name)
    except SystemExit as _e:
        if _e.code in (0, None):
            print("[OK]  ", _name)
        else:
            print("[FAIL]", _name, "exited with code", _e.code)
            FAILURES.append(_name)
    except BaseException as _e:
        import traceback
        traceback.print_exc()
        print("[FAIL]", _name, "raised", type(_e).__name__, _e)
        FAILURES.append(_name)

# ---- Extract standalone PNGs from the embedded base64 figure bundle ----
print()
print("=" * 70)
print("Extracting standalone PNG figures")
print("=" * 70)
_png_dir = os.path.join("results", "paper1_final", "figures", "png")
os.makedirs(_png_dir, exist_ok=True)
with open(os.path.join("results", "paper1_final", "figures", "figures_base64.json")) as _f:
    _figs = json.load(_f)
for _key, _b64 in _figs.items():
    _fname = "Figure_%d.png" % int(_key[3:])
    with open(os.path.join(_png_dir, _fname), "wb") as _f:
        _f.write(base64.b64decode(_b64))
print("[OK]  %d PNGs written to %s" % (len(_figs), _png_dir))

print()
print("=" * 70)
if FAILURES:
    print("PIPELINE FINISHED WITH %d FAILURE(S):" % len(FAILURES))
    for _f in FAILURES:
        print("  x", _f)
else:
    print("ALL PHASES COMPLETED SUCCESSFULLY")
print("=" * 70)
print()
print("Deliverables:")
print("  paper1_final_manuscript.html  - final manuscript (10 figures, 6 tables)")
print("  results/paper1_final/figures/png/Figure_1..10.png - standalone figures")
print("  results/... - all analysis outputs incl. paper1_final evidence package")
if FAILURES:
    _sys.exit(1)

